-- ================================================================
-- Launch stories for Lithuania (#65) and Malta (#66), EN only.
-- ES/DE/FR ride in the countries' respective translation
-- migrations (JOIN-lookup pattern, per Bulgaria/Estonia's 471/472).
--
-- Lithuania: the Sept 2024 SABIS platform consolidation, used as
-- the news hook for the more important "no B2B mandate, despite a
-- disputed 2028 figure circulating" clarification (EC factsheet,
-- independently re-fetched). Malta: the 5 Jun 2025 TSI project
-- stakeholder closing event (MTCA official page), used to explain
-- Malta's "actively studying, no committed date" posture.
-- ================================================================

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2024-09-01-lithuania-sabis-platform', '2024-09-01', '2024-09', 'Lithuania consolidated its B2G e-invoicing onto a single new platform, SABIS, replacing the older "E. sąskaita" system. Lithuania still has no B2B e-invoicing mandate — despite a "1 January 2028" figure circulating in some coverage, which traces back to an internally inconsistent European Commission factsheet and may be confused with neighbouring Latvia''s own, separately-enacted 2028 mandate.', '<h3>🇱🇹 Lithuania consolidates B2G e-invoicing onto SABIS — but B2B still has no mandate</h3>
<p>In 2024, Lithuania retired its older "E. sąskaita" B2G e-invoicing system in favour of SABIS (Sąskaitų administravimo bendroji informacinė sistema), the sole channel for structured e-invoices to Lithuanian public contracting authorities — supporting manual portal entry or Peppol BIS Billing 3.0/CII transmission. Public procurement e-invoicing has been mandatory in Lithuania since 1 July 2017, and separately, VAT-registered businesses have filed a monthly invoice-level VAT ledger (i.SAF) to the tax authority since around October 2016.</p>
<p>What Lithuania does not have is a business-to-business e-invoicing mandate. The European Commission''s own country factsheet says so directly — "there is no business-to-business (B2B) mandate" — while, confusingly, the same page separately names "1 January 2028" as a target date for mandatory e-invoicing. No enacted Lithuanian law corroborates that date, and neighbouring Latvia has a real B2B mandate of its own that was postponed to exactly 1 January 2028 — raising a real possibility that some coverage of "Lithuania 2028" is echoing Latvia''s confirmed date rather than reporting an independent Lithuanian commitment. Until an actual law appears, the only settled cross-border deadline is the EU''s ViDA floor of 1 July 2030.</p>', 'https://ec.europa.eu/digital-building-blocks/sites/spaces/einvoicingCFS/pages/881983586/2025+Lithuania+2025+eInvoicing+Country+Sheet', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2024-09-01-lithuania-sabis-platform', id FROM countries WHERE code = 'LT';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-09-01-lithuania-sabis-platform', 'en', 'Lithuania consolidates B2G e-invoicing onto SABIS — but B2B still has no mandate', 'Lithuania consolidated its B2G e-invoicing onto a single new platform, SABIS, replacing the older "E. sąskaita" system. Lithuania still has no B2B e-invoicing mandate — despite a "1 January 2028" figure circulating in some coverage, which traces back to an internally inconsistent European Commission factsheet and may be confused with neighbouring Latvia''s own, separately-enacted 2028 mandate.', '<h3>🇱🇹 Lithuania consolidates B2G e-invoicing onto SABIS — but B2B still has no mandate</h3>
<p>In 2024, Lithuania retired its older "E. sąskaita" B2G e-invoicing system in favour of SABIS (Sąskaitų administravimo bendroji informacinė sistema), the sole channel for structured e-invoices to Lithuanian public contracting authorities — supporting manual portal entry or Peppol BIS Billing 3.0/CII transmission. Public procurement e-invoicing has been mandatory in Lithuania since 1 July 2017, and separately, VAT-registered businesses have filed a monthly invoice-level VAT ledger (i.SAF) to the tax authority since around October 2016.</p>
<p>What Lithuania does not have is a business-to-business e-invoicing mandate. The European Commission''s own country factsheet says so directly — "there is no business-to-business (B2B) mandate" — while, confusingly, the same page separately names "1 January 2028" as a target date for mandatory e-invoicing. No enacted Lithuanian law corroborates that date, and neighbouring Latvia has a real B2B mandate of its own that was postponed to exactly 1 January 2028 — raising a real possibility that some coverage of "Lithuania 2028" is echoing Latvia''s confirmed date rather than reporting an independent Lithuanian commitment. Until an actual law appears, the only settled cross-border deadline is the EU''s ViDA floor of 1 July 2030.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-06-05-malta-tsi-project-closes', '2025-06-05', '2025-06', 'Malta''s tax authority closed out an EU-funded project on real-time reporting readiness, reaffirming that the country is only "actively studying" e-invoicing and digital reporting, with no domestic B2B mandate, target date, or draft legislation — aiming instead for general readiness by the EU''s 2030 ViDA deadline.', '<h3>🇲🇹 Malta wraps its real-time reporting pilot — still no B2B mandate on the table</h3>
<p>On 5 June 2025, the Malta Tax and Customs Administration (MTCA) held the stakeholder closing event for an EU Technical Support Instrument (TSI) project, "Strengthening Tax Compliance through Real-Time Reporting in Malta." It''s the most concrete recent evidence of Malta''s posture on e-invoicing: exploratory, not committal. MTCA''s own page states plainly that it is "actively studying the implementation of e-invoicing and real-time reporting," with the explicit goal of "ensuring Malta is ViDA-ready by 2030" — not an earlier domestic mandate.</p>
<p>That leaves Malta with one of the thinnest e-invoicing regimes among tracked EU countries: legal notices from late 2018 require public contracting authorities to be *able to receive* structured e-invoices, but suppliers are not required to send them, there is no domestic B2B mandate of any kind, and Malta runs no platform of its own — relying instead on the Peppol network via a contracted service provider (Pagero). Both the European Commission''s own country factsheet and MTCA''s page confirm there is no penalty regime either, for the simple reason that no mandate yet exists to enforce.</p>', 'https://mtca.gov.mt/business-tax/vat1/vat-information/e-invoicing-and-drr/e-invoicing-and-drr', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2025-06-05-malta-tsi-project-closes', id FROM countries WHERE code = 'MT';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-06-05-malta-tsi-project-closes', 'en', 'Malta wraps its real-time reporting pilot — still no B2B mandate on the table', 'Malta''s tax authority closed out an EU-funded project on real-time reporting readiness, reaffirming that the country is only "actively studying" e-invoicing and digital reporting, with no domestic B2B mandate, target date, or draft legislation — aiming instead for general readiness by the EU''s 2030 ViDA deadline.', '<h3>🇲🇹 Malta wraps its real-time reporting pilot — still no B2B mandate on the table</h3>
<p>On 5 June 2025, the Malta Tax and Customs Administration (MTCA) held the stakeholder closing event for an EU Technical Support Instrument (TSI) project, "Strengthening Tax Compliance through Real-Time Reporting in Malta." It''s the most concrete recent evidence of Malta''s posture on e-invoicing: exploratory, not committal. MTCA''s own page states plainly that it is "actively studying the implementation of e-invoicing and real-time reporting," with the explicit goal of "ensuring Malta is ViDA-ready by 2030" — not an earlier domestic mandate.</p>
<p>That leaves Malta with one of the thinnest e-invoicing regimes among tracked EU countries: legal notices from late 2018 require public contracting authorities to be *able to receive* structured e-invoices, but suppliers are not required to send them, there is no domestic B2B mandate of any kind, and Malta runs no platform of its own — relying instead on the Peppol network via a contracted service provider (Pagero). Both the European Commission''s own country factsheet and MTCA''s page confirm there is no penalty regime either, for the simple reason that no mandate yet exists to enforce.</p>');
